import torch


def gen_inputs(ctx, device):
    # Reproduce the pytest input distribution: torch.rand(shape) + 0.1
    # (lgamma requires positive values to avoid NaN/Inf).
    torch.manual_seed(0)
    shape = ctx["A__shape"]
    dtype = getattr(torch, ctx["A__dtype"])
    A = torch.rand(shape, dtype=dtype, device=device) + 0.1
    return {"A": A}


def run(A):
    # In-place lgamma on the original tensor; return the mutated tensor.
    return A.lgamma_()
